 if(argc!=3)return 2;auto source=Scene::load(argv[1]);const auto original=source.encode();const auto &before=source.active();const auto old_frames=before.material_bindings->normal_frames;const auto cps=before.material_bindings->canonical_paint_sampling;const auto count=before.deformation->morphs->targets.size();const std::filesystem::path out=argv[2];std::filesystem::create_directories(out);Document doc;doc.replace(source);ready(doc);ShapeKeyEdit create;create.name="Actual new key AFTER canonical paint UV";doc.author_shape(create);doc.save_async(out/"created.dsculpt").get();ready(doc);auto created=doc.copy_scene();const auto &object=created.active();const auto binding=object.material_bindings;const auto key=binding->key_derivation;
